"use client";

import { useState } from "react";
import { Dialog, DialogContent } from "@/components/ui/dialog"; 
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";

export default function TaskFormModal({ open, setOpen, onCreateTask }: any) {
  const [titel, setTitel] = useState("");
  const [documentType, setDocumentType] = useState("Logboek"); // Standaard Logboek
  const [sprint, setSprint] = useState(1);
  const [datum, setDatum] = useState(new Date().toISOString().split('T')[0]);

  function handleSubmit() {
    if (!titel) return alert("Voer een titel in!");

    const nieuweTaak = {
      id: Date.now(),
      titel: titel,
      document: documentType,
      sprint: sprint,
      datum: datum,
      // Lege velden voor de review (Notion-stijl invullen later)
      geleerd: "",
      nietVoldoende: "",
      actiepunten: "",
      status: "REVIEW"
    };

    onCreateTask(nieuweTaak);
    setTitel("");
    setOpen(false);
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="bg-[#0E153A]/95 border border-teal-400/30 text-teal-100 p-6 rounded-2xl shadow-2xl backdrop-blur-xl">
        <h2 className="text-2xl font-bold text-teal-300 mb-4">Nieuw Document / Taak</h2>
        
        <div className="flex flex-col gap-4">
          <div>
            <label className="text-xs text-teal-500 uppercase font-bold">Titel (bijv. Sprint Review 1)</label>
            <Input value={titel} onChange={(e) => setTitel(e.target.value)} placeholder="Naam van het item..." className="bg-[#0b1233] border-teal-400/30" />
          </div>

          <div>
            <label className="text-xs text-teal-500 uppercase font-bold">Type Document</label>
            <select 
              value={documentType} 
              onChange={(e) => setDocumentType(e.target.value)}
              className="w-full bg-[#0b1233] border border-teal-400/30 rounded-md p-2 text-sm text-teal-200"
            >
              <option value="Logboek">Logboek (Sprint Review)</option>
              <option value="Planning">Planning</option>
              <option value="Onderzoek">Onderzoek</option>
            </select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-xs text-teal-500 uppercase font-bold">Sprint nr.</label>
              <Input type="number" value={sprint} onChange={(e) => setSprint(+e.target.value)} className="bg-[#0b1233] border-teal-400/30" />
            </div>
            <div>
              <label className="text-xs text-teal-500 uppercase font-bold">Datum</label>
              <Input type="date" value={datum} onChange={(e) => setDatum(e.target.value)} className="bg-[#0b1233] border-teal-400/30 text-white" />
            </div>
          </div>

          <Button onClick={handleSubmit} className="bg-gradient-to-r from-teal-400 to-fuchsia-500 text-black font-bold mt-4">
            Item Aanmaken
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}